# Language reference topics for the extended help (help/language.fch).
# K(title, summary, syntax, detail, see, example, keys)   -- see gen.py for how they are laid out.
def K(title, summary, syntax, detail, see="", example=None, keys=None):
    return dict(title=title, summary=summary, syntax=syntax, detail=detail, see=see, example=example, keys=title if keys is None else keys)

KEYWORDS = [
K("auto", "Storage class of local variables.", ["auto type name;"],
  "Local variables declared inside a function are automatic by default, so auto is almost never written. An automatic variable lives on the stack, exists while its block runs and has no defined value until it is assigned. auto is not allowed at file scope.",
  "static register extern {Storage classes and scope}",
  "#include <stdio.h>\n\nint main(void)\n{\n    auto int count = 3;      /* same as: int count = 3; */\n\n    while (count > 0)\n        printf(\"%d \", count--);\n    printf(\"liftoff\\n\");\n    return 0;\n}"),
K("break", "Leaves the innermost loop or switch.", ["break;"],
  "break jumps to the first statement after the closest enclosing for, while, do or switch statement. Using break outside of these is an error. To leave several nested loops use goto or a flag.",
  "continue switch for while do goto",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i;\n\n    for (i = 1; i <= 100; i++) {\n        if (i * i > 50)\n            break;           /* leaves the for loop */\n    }\n    printf(\"first i with i*i > 50 is %d\\n\", i);\n    return 0;\n}"),
K("case", "Labels a statement inside a switch.", ["case constant-expression:"],
  "The value of the switch expression is compared with each case label. The label must be an integer constant expression and no two labels of one switch may have the same value. Execution continues with the labelled statement and runs on into the next label unless it is stopped with break.",
  "switch default break",
  "#include <stdio.h>\n\nint main(void)\n{\n    int c;\n\n    for (c = 'a'; c <= 'f'; c++) {\n        switch (c) {\n        case 'a': case 'e':\n            printf(\"%c is a vowel\\n\", c);\n            break;\n        default:\n            printf(\"%c is a consonant\\n\", c);\n        }\n    }\n    return 0;\n}"),
K("char", "Character type, 1 byte.", ["char name;", "signed char name;", "unsigned char name;"],
  "char holds one byte and is also used as a small integer. Plain char is signed unless Options|Compiler|Code generation|Unsigned characters is on (fcc -K). A character constant such as 'a' has type int. Arrays of char hold strings.",
  "short int unsigned signed {Character constants and escape sequences} {Strings}",
  "#include <stdio.h>\n\nint main(void)\n{\n    char letter = 'A';\n    unsigned char byte = 200;\n\n    printf(\"%c = %d\\n\", letter, letter);\n    printf(\"byte = %d, size %d\\n\", byte, (int)sizeof byte);\n    return 0;\n}"),
K("const", "Marks an object as read-only.", ["const type name = value;", "const type *pointer;      /* data is read-only */", "type *const pointer;      /* pointer is read-only */"],
  "Assigning to a const object, or through a pointer to const, is the error 'Cannot modify a const object'. A const object must get its value when it is declared. const is checked for scalars, pointers and arrays; it is not tracked for whole struct or union objects (their const members are).\n\nFunctions that only read through a pointer should take a pointer to const; string literals are best held in const char pointers.",
  "volatile {Pointers} {Type qualifiers}",
  "#include <stdio.h>\n\nstatic int length(const char *s)\n{\n    int n = 0;\n    while (*s++)             /* the string is only read */\n        n++;\n    return n;\n}\n\nint main(void)\n{\n    const int limit = 10;\n    const char *text = \"const\";\n\n    printf(\"%d %d\\n\", limit, length(text));\n    /* limit = 5;   would be: Cannot modify a const object */\n    return 0;\n}"),
K("continue", "Starts the next iteration of a loop.", ["continue;"],
  "continue skips the rest of the loop body. In a while or do loop control goes to the test; in a for loop it goes to the third expression (the step) and then to the test. It is an error outside of a loop.",
  "break for while do",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i;\n\n    for (i = 1; i <= 10; i++) {\n        if (i % 2 == 0)\n            continue;        /* skip even numbers */\n        printf(\"%d \", i);\n    }\n    printf(\"\\n\");\n    return 0;\n}"),
K("default", "Label for the cases a switch does not list.", ["default:"],
  "If no case label matches the switch expression, execution continues at the default label. A switch has at most one default label and it may appear anywhere among the cases.",
  "switch case break",
  "#include <stdio.h>\n\nstatic const char *name(int day)\n{\n    switch (day) {\n    case 6: case 7: return \"weekend\";\n    default:        return \"weekday\";\n    }\n}\n\nint main(void)\n{\n    printf(\"%s %s\\n\", name(3), name(7));\n    return 0;\n}"),
K("do", "Loop that tests its condition after the body.", ["do statement while (expression);"],
  "The body always runs at least once. The loop repeats while the expression is nonzero. Note the semicolon after the closing parenthesis.",
  "while for break continue",
  "#include <stdio.h>\n\nint main(void)\n{\n    int n = 1234, digits = 0;\n\n    do {\n        digits++;\n        n /= 10;\n    } while (n != 0);\n    printf(\"%d digits\\n\", digits);\n    return 0;\n}"),
K("double", "Double precision floating-point type, 8 bytes.", ["double name;"],
  "IEEE 754 64-bit value with about 15 decimal digits. All floating-point arithmetic is done in double precision. long double is the same type as double. Floating constants without a suffix are double. printf prints a double with %f %e or %g and scanf reads it with %lf.",
  "float {Floating constants} {printf formats}",
  "#include <stdio.h>\n\nint main(void)\n{\n    double radius = 2.5;\n    double area = 3.14159265358979 * radius * radius;\n\n    printf(\"area = %.4f\\n\", area);\n    printf(\"size = %d bytes\\n\", (int)sizeof(double));\n    return 0;\n}"),
K("else", "Alternative branch of an if statement.", ["if (expression) statement else statement"],
  "An else belongs to the nearest preceding if that has no else. Use braces to make another grouping.",
  "if switch {Conditional operator}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int n;\n\n    for (n = -1; n <= 1; n++) {\n        if (n < 0)\n            printf(\"negative\\n\");\n        else if (n == 0)\n            printf(\"zero\\n\");\n        else\n            printf(\"positive\\n\");\n    }\n    return 0;\n}"),
K("enum", "Defines a set of named integer constants.", ["enum tag { name, name = value, ... };", "enum tag variable;"],
  "Constants without a value are one more than the previous one; the first is 0. The constants have type int and can be used wherever an integer constant is allowed. An enum variable is an int, or with Options|Compiler|Code generation|Treat enums as ints turned off (fcc -b-) the smallest of char, short and int that holds all values.\n\nA trailing comma after the last constant is accepted.",
  "typedef {Integer types} switch",
  "#include <stdio.h>\n\nenum color { RED, GREEN = 5, BLUE };\n\nint main(void)\n{\n    enum color c = BLUE;\n\n    printf(\"RED=%d GREEN=%d BLUE=%d\\n\", RED, GREEN, BLUE);\n    printf(\"c is %s\\n\", c == BLUE ? \"blue\" : \"other\");\n    return 0;\n}"),
K("extern", "Declares an object or function defined elsewhere.", ["extern type name;", "extern type function(parameters);"],
  "extern describes a name without creating it; the definition must exist in another source file of the program or in the library, otherwise the linker reports 'Undefined symbol'. Functions have external linkage by default, so extern is optional in their declarations. Several files given to fcc, or listed in a project, form one program.",
  "static auto {Storage classes and scope} {Functions}",
  "#include <stdio.h>\n\nint counter = 0;             /* the definition */\n\nstatic void bump(void)\n{\n    extern int counter;      /* refers to the global above */\n    counter++;\n}\n\nint main(void)\n{\n    bump(); bump();\n    printf(\"counter = %d\\n\", counter);\n    return 0;\n}"),
K("float", "Single precision floating-point type, 4 bytes.", ["float name;"],
  "IEEE 754 32-bit value with about 7 decimal digits. Arithmetic is performed in double precision and the result is rounded to float when it is stored. Function arguments of type float are passed as double. Use the suffix f for a float constant.",
  "double {Floating constants}",
  "#include <stdio.h>\n\nint main(void)\n{\n    float third = 1.0f / 3.0f;\n\n    printf(\"%.10f\\n\", third);\n    printf(\"size = %d bytes\\n\", (int)sizeof(float));\n    return 0;\n}"),
K("for", "Loop with initialisation, test and step.", ["for (expression1; expression2; expression3) statement", "for (declaration; expression2; expression3) statement"],
  "expression1 runs once, then the loop repeats while expression2 is nonzero; expression3 runs after each pass. Any of the three may be left out; a missing test is always true. A variable declared in the first part is only visible in the loop.",
  "while do break continue",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i, sum = 0;\n\n    for (i = 1; i <= 10; i++)\n        sum += i;\n    printf(\"sum = %d\\n\", sum);\n\n    for (;;) {               /* endless loop */\n        if (sum-- < 50) break;\n    }\n    printf(\"sum = %d\\n\", sum);\n    return 0;\n}"),
K("goto", "Jumps to a label in the same function.", ["goto label;", "label: statement"],
  "A label is an identifier followed by a colon. Labels have function scope, so the jump can go forward or backward but never into another function. goto is useful for leaving several nested loops or for common clean-up code.",
  "break continue return",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i, j;\n\n    for (i = 0; i < 10; i++)\n        for (j = 0; j < 10; j++)\n            if (i * j == 42)\n                goto found;\n    printf(\"not found\\n\");\n    return 1;\nfound:\n    printf(\"%d * %d = 42\\n\", i, j);\n    return 0;\n}"),
K("if", "Conditional execution.", ["if (expression) statement", "if (expression) statement else statement"],
  "The statement runs when the expression is nonzero. The expression must have a scalar type (integer, floating or pointer). A pointer is true when it is not NULL. With -wcln the compiler warns when the condition is a constant, with -wasn (Possibly incorrect assignment) when it is an assignment such as if (a = b).",
  "else switch {Relational and logical operators}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int year = 2024;\n\n    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))\n        printf(\"%d is a leap year\\n\", year);\n    else\n        printf(\"%d is not a leap year\\n\", year);\n    return 0;\n}"),
K("int", "Integer type, 4 bytes.", ["int name;", "signed int name;", "unsigned int name;"],
  "int is 32 bits in Flash C (it was 16 bits in DOS compilers), range -2147483648 to 2147483647; unsigned int is 0 to 4294967295. Integer arithmetic is done in int or, if an operand is long, in long. Overflow wraps around.",
  "short long char unsigned signed {Integer types} {Type conversions}",
  "#include <stdio.h>\n#include <limits.h>\n\nint main(void)\n{\n    int big = INT_MAX;\n    unsigned int u = 4000000000u;\n\n    printf(\"%d %u\\n\", big, u);\n    printf(\"size = %d bytes\\n\", (int)sizeof(int));\n    return 0;\n}"),
K("long", "Long integer type, 8 bytes.", ["long name;", "unsigned long name;"],
  "long is 64 bits in Flash C, range -9223372036854775808 to 9223372036854775807. Pointers are the same size. long long is accepted and means long. Constants get the suffix l or L; printf uses %ld.",
  "int short unsigned {Integer constants} {Integer types}",
  "#include <stdio.h>\n\nint main(void)\n{\n    long f = 1;\n    int i;\n\n    for (i = 2; i <= 20; i++)\n        f *= i;\n    printf(\"20! = %ld\\n\", f);\n    printf(\"size = %d bytes\\n\", (int)sizeof(long));\n    return 0;\n}"),
K("register", "Asks that a variable be kept in a register.", ["register type name;"],
  "register is a hint. Flash C does not allocate registers, so the keyword is accepted and has no effect on the generated code. It is only allowed for local variables and parameters; at file scope it is an error.",
  "auto static {Storage classes and scope}",
  "#include <stdio.h>\n\nint main(void)\n{\n    register int i;\n    long sum = 0;\n\n    for (i = 0; i < 1000; i++)\n        sum += i;\n    printf(\"%ld\\n\", sum);\n    return 0;\n}"),
K("return", "Leaves a function, optionally with a value.", ["return;", "return expression;"],
  "The expression is converted to the return type of the function. Falling off the end of a function that should return a value gives the warning 'Function should return a value' and a result of 0. A void function must not return a value ('Void functions may not return a value'). Returning from main ends the program with that exit code.",
  "{Functions} void main goto",
  "#include <stdio.h>\n\nstatic int max(int a, int b)\n{\n    if (a > b)\n        return a;\n    return b;\n}\n\nint main(void)\n{\n    printf(\"%d\\n\", max(3, 9));\n    return 0;                /* exit code 0 */\n}"),
K("short", "Short integer type, 2 bytes.", ["short name;", "short int name;", "unsigned short name;"],
  "short holds -32768 to 32767, unsigned short 0 to 65535. In expressions short values are first converted to int. printf uses %hd.",
  "int long char {Integer types}",
  "#include <stdio.h>\n\nint main(void)\n{\n    short s = 32767;\n    unsigned short u = 65535;\n\n    s++;                     /* wraps to -32768 */\n    printf(\"%d %u\\n\", s, u);\n    printf(\"size = %d bytes\\n\", (int)sizeof(short));\n    return 0;\n}"),
K("signed", "Integer type that can hold negative values.", ["signed char name;", "signed int name;"],
  "Integer types are signed by default; signed matters mainly for char, where plain char may be unsigned (fcc -K).",
  "unsigned char int",
  "#include <stdio.h>\n\nint main(void)\n{\n    signed char c = -5;\n    signed s = -100000;      /* signed alone means signed int */\n\n    printf(\"%d %d\\n\", c, s);\n    return 0;\n}"),
K("sizeof", "Size of a type or object in bytes.", ["sizeof expression", "sizeof (type)"],
  "The result is a compile-time constant of type unsigned long (size_t). The expression is not evaluated. sizeof an array gives the size of the whole array, which is the usual way to find the number of elements. sizeof cannot be applied to a bit field, a function or an incomplete type.",
  "{Data types} {Arrays} {Pointers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int table[10];\n    char *p = 0;\n\n    printf(\"int %d, long %d, pointer %d\\n\", (int)sizeof(int), (int)sizeof(long), (int)sizeof p);\n    printf(\"elements: %d\\n\", (int)(sizeof table / sizeof table[0]));\n    return 0;\n}"),
K("static", "Limits the scope of a name or keeps a local alive.", ["static type name = constant;", "static type function(parameters) { ... }"],
  "At file scope static gives a variable or function internal linkage: it can only be used in its own source file. Inside a function static creates a variable that keeps its value between calls; it is initialised once, before the program starts (to 0 if there is no initialiser), and the initialiser must be a constant.",
  "extern auto {Storage classes and scope}",
  "#include <stdio.h>\n\nstatic int next_id(void)\n{\n    static int id = 100;     /* kept between calls */\n    return id++;\n}\n\nint main(void)\n{\n    printf(\"%d %d %d\\n\", next_id(), next_id(), next_id());\n    return 0;\n}"),
K("struct", "Groups variables of different types.", ["struct tag { type member; ... };", "struct tag variable;", "variable.member   pointer->member"],
  "Members are stored in order and padded to their natural alignment (Options|Compiler|Code generation|Align structure members; with it off, fcc -a-, there is no padding). A structure can be assigned, passed to a function and returned by value; the warning 'Structure passed by value' is available (-wstv). A structure cannot contain itself but may contain a pointer to its own type. Members can be bit fields.",
  "union typedef {Member access operators} {Bit fields} {Initializers}",
  "#include <stdio.h>\n#include <string.h>\n\nstruct person {\n    char name[20];\n    int age;\n};\n\nstatic void birthday(struct person *p)\n{\n    p->age++;\n}\n\nint main(void)\n{\n    struct person who;\n\n    strcpy(who.name, \"Ann\");\n    who.age = 30;\n    birthday(&who);\n    printf(\"%s is %d (struct is %d bytes)\\n\", who.name, who.age, (int)sizeof who);\n    return 0;\n}"),
K("switch", "Multi-way branch on an integer value.", ["switch (expression) statement"],
  "The expression must have an integer type. Control goes to the case label with the same value, or to default, or past the switch when there is neither. Without break execution falls through to the next label. Declarations are not allowed directly after a label.",
  "case default break if",
  "#include <stdio.h>\n\nint main(void)\n{\n    int n;\n\n    for (n = 1; n <= 4; n++) {\n        switch (n) {\n        case 1: printf(\"one \");\n        case 2: printf(\"two \");   /* case 1 falls through */\n                break;\n        case 3: printf(\"three \");\n                break;\n        default: printf(\"many \");\n        }\n    }\n    printf(\"\\n\");\n    return 0;\n}"),
K("typedef", "Gives a new name to a type.", ["typedef type name;"],
  "A typedef declaration looks like a variable declaration with typedef in front; the name becomes a synonym for the type. Typedefs make structure and function pointer types readable. Repeating a typedef in the same scope is an error.",
  "struct enum {Function pointers}",
  "#include <stdio.h>\n\ntypedef unsigned char byte;\ntypedef struct { int x, y; } point;\ntypedef int (*binop)(int, int);\n\nstatic int add(int a, int b) { return a + b; }\n\nint main(void)\n{\n    byte b = 255;\n    point p = { 3, 4 };\n    binop f = add;\n\n    printf(\"%d %d %d\\n\", b, p.x + p.y, f(1, 2));\n    return 0;\n}"),
K("union", "Overlays several members in the same storage.", ["union tag { type member; ... };"],
  "All members start at the same address and the union is as large as its largest member. Only the member that was stored last holds a meaningful value. A union can be used to look at the same bytes as different types.",
  "struct typedef {Member access operators}",
  "#include <stdio.h>\n\nunion word {\n    unsigned int whole;\n    unsigned char byte[4];\n};\n\nint main(void)\n{\n    union word w;\n\n    w.whole = 0x01020304;\n    printf(\"%d %d %d %d (size %d)\\n\", w.byte[0], w.byte[1], w.byte[2], w.byte[3], (int)sizeof w);\n    return 0;\n}"),
K("unsigned", "Integer type without negative values.", ["unsigned char name;", "unsigned short name;", "unsigned int name;", "unsigned long name;"],
  "unsigned alone means unsigned int. Arithmetic on unsigned values wraps around modulo 2^N. When a signed and an unsigned operand of the same size are mixed, the signed one is converted to unsigned, which can make a comparison such as -1 < 1u false.",
  "signed int long {Type conversions}",
  "#include <stdio.h>\n\nint main(void)\n{\n    unsigned int u = 0;\n\n    u--;                     /* wraps around */\n    printf(\"%u\\n\", u);\n    printf(\"%d\\n\", -1 < 1u);   /* 0: -1 becomes unsigned */\n    return 0;\n}"),
K("void", "No value / no type.", ["void function(void);", "void *pointer;"],
  "As a return type void means the function returns nothing. In a parameter list (void) means no parameters, which is different from () that declares nothing about the parameters. A void * can hold the address of any object and is converted to and from other pointer types without a cast; it cannot be dereferenced or used in pointer arithmetic.",
  "{Functions} {Pointers} return",
  "#include <stdio.h>\n#include <stdlib.h>\n\nstatic void hello(void)\n{\n    printf(\"hello\\n\");\n}\n\nint main(void)\n{\n    void *block = malloc(16);      /* void * converts to any pointer */\n    int *p = block;\n\n    *p = 7;\n    hello();\n    printf(\"%d\\n\", *p);\n    free(block);\n    return 0;\n}"),
K("volatile", "Marks an object that may change unexpectedly.", ["volatile type name;"],
  "volatile tells the compiler that a variable can change outside the normal flow of the program, for example in a signal handler. Flash C reads and writes variables exactly as written in the program and does not keep them in registers between statements, so the qualifier is accepted and the code is the same.",
  "const {Type qualifiers} signal",
  "#include <stdio.h>\n#include <signal.h>\n\nstatic volatile int got_signal = 0;\n\nstatic void handler(int sig)\n{\n    got_signal = 1;\n}\n\nint main(void)\n{\n    signal(SIGINT, handler);\n    raise(SIGINT);\n    printf(\"got_signal = %d\\n\", got_signal);\n    return 0;\n}"),
K("while", "Loop that tests its condition before the body.", ["while (expression) statement"],
  "The statement is repeated as long as the expression is nonzero; it may not run at all. while (1) is an endless loop that is left with break, return or goto.",
  "do for break continue",
  "#include <stdio.h>\n\nint main(void)\n{\n    int n = 27, steps = 0;\n\n    while (n != 1) {\n        n = (n % 2) ? 3 * n + 1 : n / 2;\n        steps++;\n    }\n    printf(\"%d steps\\n\", steps);\n    return 0;\n}"),
]

# near far huge cdecl pascal interrupt
EXT_KEYWORDS = K("Extended keywords", "near, far, huge, cdecl, pascal and interrupt.", ["type near name;      type far *p;", "int cdecl f(void);    void interrupt handler();"],
  "These keywords come from 16-bit DOS compilers, where they selected pointer sizes, calling conventions and interrupt handlers. Flash C produces flat 64-bit code, so the keywords are accepted and ignored: an existing program that uses them still compiles, but they change nothing.\n\nWith Options|Compiler|Source|Keywords set to ANSI (fcc -A) they are not keywords at all and can be used as ordinary identifiers, which is what strict ANSI C requires.",
  "{Not supported DOS features} {Differences from classic compilers}",
  "#include <stdio.h>\n\nint cdecl twice(int x)       /* cdecl is ignored */\n{\n    return x * 2;\n}\n\nint main(void)\n{\n    char far *p = \"far pointers are plain pointers\";\n\n    printf(\"%s %d\\n\", p, twice(21));\n    return 0;\n}",
  keys="near far huge cdecl pascal interrupt _near _far _huge")

OPERATORS = [
K("Arithmetic operators", "+ - * / % and unary + -.", ["a + b   a - b   a * b   a / b   a % b   +a   -a"],
  "The usual conversions bring both operands to a common type first (see {Type conversions}). Integer division truncates toward zero; the result of % has the sign of the left operand. Division or remainder by zero stops the program with a run-time error; with a constant divisor the compiler warns 'Division by zero'. Integer overflow wraps around.\n\nPointer arithmetic: pointer + n and pointer - n move by n elements, and pointer - pointer gives the number of elements between them as a long.",
  "{Operator precedence} {Assignment operators} {Pointers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    printf(\"%d %d\\n\", 7 / 2, -7 / 2);     /* 3 -3 */\n    printf(\"%d %d\\n\", 7 % 3, -7 % 3);     /* 1 -1 */\n    printf(\"%.2f\\n\", 7 / 2.0);             /* 3.50 */\n    return 0;\n}",
  keys="+ - * / % arithmetic operator"),
K("Relational and logical operators", "< <= > >= == != && || !", ["a < b  a <= b  a > b  a >= b  a == b  a != b", "a && b   a || b   !a"],
  "Comparisons and logical operators produce the int 1 (true) or 0 (false). Any nonzero value counts as true. && and || evaluate the left operand first and skip the right one when the result is known (short-circuit), so a pointer can be tested and used in one expression: p && p->next. Do not confuse == with =; the warning 'Possibly incorrect assignment' catches if (a = b).",
  "if while {Bitwise and shift operators} {Operator precedence}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a = 5, b = 0;\n\n    printf(\"%d %d %d\\n\", a > 3, a == b, !b);\n    printf(\"%d\\n\", b != 0 && 10 / b > 1);   /* no division: b != 0 is false */\n    return 0;\n}",
  keys="&& || ! == != <= >= relational logical"),
K("Bitwise and shift operators", "& | ^ ~ << >>", ["a & b   a | b   a ^ b   ~a   a << n   a >> n"],
  "& | ^ work on every bit of the operands, ~ inverts all bits. a << n shifts left, filling with zeros; a >> n shifts right, and for a signed negative value it keeps the sign bit (arithmetic shift). The shift count must be smaller than the width of the left operand. The result type is the promoted type of the left operand.\n\nThe warning 'Ambiguous operators need parentheses' (-wamb) points at expressions such as a & b | c or a << b + c.",
  "{Relational and logical operators} {Assignment operators} {Operator precedence}",
  "#include <stdio.h>\n\nint main(void)\n{\n    unsigned flags = 0;\n\n    flags |= 1 << 3;         /* set bit 3 */\n    flags |= 1 << 0;\n    flags &= ~1u;            /* clear bit 0 */\n    printf(\"flags = 0x%x, bit 3 is %s\\n\", flags, (flags & (1 << 3)) ? \"set\" : \"clear\");\n    return 0;\n}",
  keys="& | ^ ~ << >> bitwise shift"),
K("Assignment operators", "= += -= *= /= %= &= |= ^= <<= >>=", ["lvalue = expression", "lvalue op= expression"],
  "The value of the expression is converted to the type of the left side and stored. An assignment is itself an expression whose value is the stored value, so a = b = 0 works. a op= b means a = a op b except that a is evaluated only once. Assigning to a const object is an error.",
  "{Increment and decrement} {Arithmetic operators} const",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a, b, c = 10;\n\n    a = b = 3;               /* both are 3 */\n    c += a * b;              /* c = c + a * b */\n    c <<= 1;\n    printf(\"%d %d %d\\n\", a, b, c);\n    return 0;\n}",
  keys="= += -= *= /= %= &= |= ^= <<= >>= assignment"),
K("Increment and decrement", "++ and --", ["++lvalue   --lvalue   lvalue++   lvalue--"],
  "The prefix form changes the object and yields the new value, the postfix form yields the old value. On a pointer the step is one element. Do not change the same object twice in one expression (i = i++ is undefined).",
  "{Assignment operators} {Pointers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i = 5;\n    int a = i++;             /* a = 5, i = 6 */\n    int b = ++i;             /* i = 7, b = 7 */\n\n    printf(\"%d %d %d\\n\", a, b, i);\n    return 0;\n}",
  keys="++ -- increment decrement"),
K("Conditional operator", "expression ? a : b", ["condition ? expression1 : expression2"],
  "Only one of the two result expressions is evaluated. Their types are brought to a common type. The operator has low precedence and groups from right to left, so a ? b : c ? d : e means a ? b : (c ? d : e).",
  "if else {Operator precedence}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int n;\n\n    for (n = 0; n < 3; n++)\n        printf(\"%d item%s\\n\", n, n == 1 ? \"\" : \"s\");\n    return 0;\n}",
  keys="?: ? ternary conditional"),
K("Comma operator", "expression1 , expression2", ["expression , expression"],
  "Evaluates the left expression, discards it, then evaluates the right one and yields its value. It is mostly used in the parts of a for statement. In argument lists and declarations the comma is only a separator; use parentheses to get the operator: f((a, b)).",
  "for {Operator precedence}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i, j;\n\n    for (i = 0, j = 10; i < j; i++, j--)\n        ;\n    printf(\"%d %d\\n\", i, j);\n    return 0;\n}",
  keys=", comma"),
K("Address and indirection operators", "& (address of) and * (indirection)", ["&lvalue", "*pointer"],
  "&x is a pointer to x; it cannot be applied to a bit field or a register object. *p is the object p points to; it may be used on the left of an assignment. * and & undo each other: *&x is x. Dereferencing a null or invalid pointer ends the program with a segmentation fault.",
  "{Pointers} {Arrays} {Member access operators}",
  "#include <stdio.h>\n\nstatic void swap(int *a, int *b)\n{\n    int t = *a;\n    *a = *b;\n    *b = t;\n}\n\nint main(void)\n{\n    int x = 1, y = 2;\n\n    swap(&x, &y);\n    printf(\"%d %d\\n\", x, y);\n    return 0;\n}",
  keys="& * address indirection dereference"),
K("Member access operators", ". -> and []", ["structure.member", "pointer->member", "array[index]"],
  "a.b selects a member of a structure or union object; p->b is the same as (*p).b. a[i] is *(a + i), so it also works with a pointer, and i[a] means the same. Subscripts are not range checked.",
  "struct union {Arrays} {Address and indirection operators}",
  "#include <stdio.h>\n\nstruct node { int value; struct node *next; };\n\nint main(void)\n{\n    struct node b = { 2, 0 };\n    struct node a = { 1, &b };\n    struct node *p;\n\n    for (p = &a; p; p = p->next)\n        printf(\"%d \", p->value);\n    printf(\"\\n\");\n    return 0;\n}",
  keys=". -> [] member subscript"),
K("Cast operator", "(type) expression", ["(type) expression"],
  "Converts the value of the expression to the type. Casts are used to force floating-point division, to convert between pointer types and to silence the pointer conversion warnings. A cast does not make an lvalue. The cast to void discards a value.",
  "{Type conversions} sizeof {Pointers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a = 7, b = 2;\n\n    printf(\"%d\\n\", a / b);                  /* 3 */\n    printf(\"%.2f\\n\", (double)a / b);        /* 3.50 */\n    printf(\"%d\\n\", (int)3.99);               /* 3 */\n    return 0;\n}",
  keys="cast"),
K("Operator precedence", "Order in which operators are applied.", [],
  "Highest precedence first; operators in one row have equal precedence.\n\n   () [] -> .                          left to right\n   ! ~ ++ -- + - * & (type) sizeof     right to left (unary)\n   * / %                               left to right\n   + -\n   << >>\n   < <= > >=\n   == !=\n   &\n   ^\n   |\n   &&\n   ||\n   ?:                                  right to left\n   = += -= *= /= %= &= ^= |= <<= >>=   right to left\n   ,                                   left to right\n\nThe order in which operands are evaluated is not defined, except for && || ?: and the comma. Add parentheses when in doubt; -wamb warns about the mixes people most often get wrong.",
  "{Arithmetic operators} {Bitwise and shift operators} {Keywords and operators}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a = 2, b = 3, c = 4;\n\n    printf(\"%d\\n\", a + b * c);          /* 14 */\n    printf(\"%d\\n\", (a + b) * c);        /* 20 */\n    printf(\"%d\\n\", a | b & c);          /* & first: 2 | 0 = 2 */\n    printf(\"%d\\n\", a < b == 1);         /* (a < b) == 1 */\n    return 0;\n}",
  keys="precedence associativity"),
]

CONCEPTS = [
K("Data types", "The types of Flash C and their sizes.", [],
  "   char                 1 byte      -128 .. 127 (or 0 .. 255 with -K)\n   short                2 bytes     -32768 .. 32767\n   int                  4 bytes     -2147483648 .. 2147483647\n   long                 8 bytes     64-bit\n   unsigned versions    same sizes, 0 .. 2^N-1\n   float                4 bytes     about 7 digits\n   double               8 bytes     about 15 digits\n   pointer              8 bytes\n   enum                 as int (or the smallest fitting type with -b-)\n\nlong long is long, long double is double. Compare with DOS compilers, where int and pointers were 16 bits: code that depends on that size has to be reviewed.\n\nDerived types are pointers, arrays, functions, structures and unions. wchar_t is a 32-bit int.",
  "{Integer types} {Floating constants} char int long double struct pointers sizeof",
  "#include <stdio.h>\n\nint main(void)\n{\n    printf(\"char %d, short %d, int %d, long %d\\n\", (int)sizeof(char), (int)sizeof(short), (int)sizeof(int), (int)sizeof(long));\n    printf(\"float %d, double %d, pointer %d\\n\", (int)sizeof(float), (int)sizeof(double), (int)sizeof(void *));\n    return 0;\n}",
  keys="types size ranges"),
K("Integer types", "char, short, int and long with their limits.", [],
  "The ranges are in <limits.h>: CHAR_BIT, CHAR_MIN, CHAR_MAX, SCHAR_MIN, SCHAR_MAX, UCHAR_MAX, SHRT_MIN, SHRT_MAX, USHRT_MAX, INT_MIN, INT_MAX, UINT_MAX, LONG_MIN, LONG_MAX, ULONG_MAX.\n\nSigned overflow and unsigned overflow both wrap around in the generated code. A conversion to a smaller type keeps the low bits.",
  "{Data types} {Type conversions} {Integer constants} char short int long unsigned",
  "#include <stdio.h>\n#include <limits.h>\n\nint main(void)\n{\n    printf(\"short %d..%d\\n\", SHRT_MIN, SHRT_MAX);\n    printf(\"int   %d..%d\\n\", INT_MIN, INT_MAX);\n    printf(\"long  %ld..%ld\\n\", LONG_MIN, LONG_MAX);\n    return 0;\n}",
  keys="limits.h integer INT_MAX"),
K("Integer constants", "Decimal, octal and hexadecimal numbers.", ["123   0777   0x1F   123u   123L   123UL"],
  "A constant that starts with 0 is octal, with 0x or 0X is hexadecimal, otherwise decimal. The suffix u makes it unsigned, l makes it long; they can be combined. Without a suffix the constant has the first of int, unsigned int (hex and octal only), long, unsigned long in which it fits. Digits 8 and 9 in an octal constant are an error.",
  "{Floating constants} {Character constants and escape sequences} {Integer types}",
  "#include <stdio.h>\n\nint main(void)\n{\n    printf(\"%d %d %d\\n\", 255, 0377, 0xFF);   /* all 255 */\n    printf(\"%lu\\n\", 4294967296UL);\n    printf(\"%d\\n\", (int)sizeof 3000000000);  /* does not fit int: 8 */\n    return 0;\n}",
  keys="constant octal hexadecimal 0x"),
K("Floating constants", "Numbers with a decimal point or exponent.", ["3.14   .5   2.   1e10   1.5E-3   2.5f   1.0L"],
  "A floating constant has type double unless it ends in f or F (float) or l or L (long double, the same as double). The exponent is e or E followed by an optionally signed decimal number. Floating point is not allowed in #if expressions.",
  "{Integer constants} double float",
  "#include <stdio.h>\n\nint main(void)\n{\n    double a = 1.5e3, b = .25;\n    float c = 0.1f;\n\n    printf(\"%g %g %g\\n\", a, b, c);\n    return 0;\n}",
  keys="floating real exponent"),
K("Character constants and escape sequences", "'a', '\\n', '\\x41' and L'a'.", ["'c'   '\\n'   '\\012'   '\\x1B'   L'c'"],
  "A character constant has type int. Escape sequences:\n\n   \\n new-line      \\t tab            \\v vertical tab\n   \\b backspace     \\r return         \\f form feed\n   \\a alert         \\\\ backslash      \\' quote\n   \\\" double quote  \\? question mark\n   \\ooo octal (up to 3 digits)   \\xhh hexadecimal\n\nThe same escapes are used in string literals. A wide character constant L'x' has type wchar_t (32-bit int).",
  "{Strings} char {Integer constants}",
  "#include <stdio.h>\n\nint main(void)\n{\n    printf(\"tab:\\there\\n\");\n    printf(\"%c%c%c\\n\", 'A', '\\x42', '\\103');   /* ABC */\n    printf(\"quote: \\\"%c\\\" bell:\\a\\n\", '\\'');\n    return 0;\n}",
  keys="escape character constant \\n \\t \\0"),
K("Strings", "String literals and character arrays.", ["\"text\"   char name[] = \"text\";   char *p = \"text\";"],
  "A string literal is an array of char ending with a zero byte, so \"abc\" occupies 4 bytes. Adjacent literals are joined: \"ab\" \"cd\" is \"abcd\". A character array initialised from a literal is a modifiable copy; a pointer initialised from a literal points at the literal itself, which should not be changed. With Options|Compiler|Code generation|Duplicate strings merged (fcc -d) identical literals share one copy. Wide strings are written L\"text\". <string.h> has the functions that work on strings.",
  "{Library: string} {Arrays} {Character constants and escape sequences} char",
  "#include <stdio.h>\n#include <string.h>\n\nint main(void)\n{\n    char buf[32] = \"Flash\";\n    const char *msg = \"adjacent \" \"literals\";\n\n    strcat(buf, \" C\");\n    printf(\"%s (%d chars, array %d bytes)\\n\", buf, (int)strlen(buf), (int)sizeof buf);\n    puts(msg);\n    return 0;\n}",
  keys="string literal"),
K("Identifiers", "Names of variables, functions, types and labels.", [],
  "An identifier starts with a letter or underscore and continues with letters, digits and underscores. Case is significant. Options|Compiler|Source|Identifier Length (fcc -iN) sets how many leading characters are significant; the default of 32 is also the maximum. Names that start with two underscores are reserved for the compiler and library. Keywords cannot be used as identifiers.",
  "{Keywords and operators} {Declarations}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int count = 1, Count = 2, _count = 3;   /* three different names */\n\n    printf(\"%d\\n\", count + Count + _count);\n    return 0;\n}",
  keys="identifier name"),
K("Comments", "/* ... */ and // ... comments.", ["/* comment */", "// comment to the end of the line"],
  "A /* comment */ may span lines and is replaced by one space. Comments do not nest unless Options|Compiler|Source|Nested comments is on (fcc -C). A // comment runs to the end of the line; it is a C99 extension and is refused with Keywords set to ANSI (fcc -A). To disable a block of code that contains comments use #if 0 ... #endif.",
  "#if {Preprocessor}",
  "#include <stdio.h>\n\nint main(void)\n{\n    /* a block comment\n       over two lines */\n    printf(\"one\\n\");   // a line comment\n#if 0\n    printf(\"this is compiled out\\n\");\n#endif\n    return 0;\n}",
  keys="comment /* //"),
K("Declarations", "How variables, functions and types are declared.", ["storage-class qualifier type declarator = initializer, ... ;"],
  "A declaration names a type and one or more declarators. Declarators combine * (pointer to), [] (array of) and () (function returning) and are read from the name outward:\n\n   int *p;          p is a pointer to int\n   int a[10];       a is an array of 10 int\n   int *a[10];      a is an array of 10 pointers to int\n   int (*a)[10];    a is a pointer to an array of 10 int\n   int f(void);     f is a function returning int\n   int (*f)(void);  f is a pointer to a function returning int\n\nDeclarations may appear anywhere in a block, not only at its start. Use typedef to give complicated types a name. The warning \"'x' is declared but never used\" is available (-wuse).",
  "{Storage classes and scope} typedef {Pointers} {Arrays} {Function pointers} {Initializers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a = 1, *p = &a, v[3] = { 4, 5, 6 };\n    int (*pv)[3] = &v;\n\n    printf(\"%d %d\\n\", *p, (*pv)[2]);\n    for (int i = 0; i < 3; i++)       /* declaration inside for */\n        printf(\"%d \", v[i]);\n    printf(\"\\n\");\n    return 0;\n}",
  keys="declaration declarator"),
K("Storage classes and scope", "Where a name is visible and how long it lives.", [],
  "Scope\n   file       declared outside functions: visible to the end of the file\n   function   labels only\n   block      declared inside { }: visible to the end of the block\n   prototype  parameter names in a prototype\n\nA name in an inner block hides the same name in an outer one.\n\nStorage\n   automatic  locals and parameters (stack); keyword auto\n   static     file-scope objects and static locals: exist for the whole\n              run and start as zero\n   external   extern: defined in another file\n\nUninitialised automatic variables contain garbage; static and global objects are zeroed.",
  "auto static extern register {Declarations}",
  "#include <stdio.h>\n\nint x = 1;                   /* file scope */\n\nint main(void)\n{\n    int x = 2;               /* hides the global */\n\n    {\n        int x = 3;           /* hides the one above */\n        printf(\"%d\\n\", x);\n    }\n    printf(\"%d\\n\", x);\n    return 0;\n}",
  keys="scope storage linkage visibility"),
K("Type qualifiers", "const and volatile.", ["const type name;   volatile type name;   const volatile type name;"],
  "A qualifier applies to the type on its left (or, at the start of a declaration, to the base type). In const char *p the characters are read-only; in char *const p the pointer is read-only. See {const} and {volatile}.",
  "const volatile {Pointers}",
  "#include <stdio.h>\n\nint main(void)\n{\n    char text[] = \"abc\";\n    const char *a = text;        /* cannot change *a */\n    char *const b = text;        /* cannot change b */\n\n    b[0] = 'X';\n    printf(\"%s\\n\", a);\n    return 0;\n}",
  keys="qualifier"),
K("Pointers", "Variables that hold addresses.", ["type *name;   *p   &x   p + n   p - q"],
  "A pointer is 8 bytes. Pointer arithmetic is scaled by the size of the pointed-to type: p + 1 is the next element. Pointers of the same type can be compared and subtracted if they point into the same array. A null pointer (0, NULL) points nowhere and compares false. void * converts to and from any object pointer without a cast.\n\nConverting between integers and pointers is non-portable; the compiler warns 'Non-portable pointer conversion' (-wrpt) and for different pointee types 'Suspicious pointer conversion' (-wsus); char versus unsigned char gives 'Mixing pointers to signed and unsigned char' (-wucp).",
  "{Address and indirection operators} {Arrays} {Function pointers} void const",
  "#include <stdio.h>\n\nint main(void)\n{\n    int v[4] = { 10, 20, 30, 40 };\n    int *p = v;\n\n    p += 2;\n    printf(\"%d %d %d\\n\", *p, p[1], (int)(p - v));   /* 30 40 2 */\n    return 0;\n}",
  keys="pointer pointers NULL"),
K("Arrays", "Fixed-size sequences of elements.", ["type name[size];", "type name[] = { value, ... };", "type name[rows][columns];"],
  "Elements are numbered from 0 and stored one after the other; there is no range checking. The size must be a constant (variable-length arrays are not supported). In most expressions an array turns into a pointer to its first element, so arrays are passed to functions as pointers and the callee cannot find the size. The exceptions are sizeof and &. Multi-dimensional arrays are arrays of arrays, stored row by row.",
  "{Pointers} {Initializers} sizeof {Strings}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int grid[2][3] = { { 1, 2, 3 }, { 4, 5, 6 } };\n    int total = 0, r, c;\n\n    for (r = 0; r < 2; r++)\n        for (c = 0; c < 3; c++)\n            total += grid[r][c];\n    printf(\"total %d, %d elements\\n\", total, (int)(sizeof grid / sizeof(int)));\n    return 0;\n}",
  keys="array arrays subscript"),
K("Initializers", "Giving an object a value when it is declared.", ["type name = expression;", "type name[] = { value, value, ... };", "struct tag name = { value, ... };", "type name[] = { [2] = 5 };   struct tag name = { .member = value };"],
  "Static and global objects need constant initialisers and are zero when there is none. Automatic objects may use any expression. Braces may be nested for arrays of arrays and structures, and missing trailing values are zero. A char array can be initialised with a string; when its size is left out it is taken from the initialiser. Designated initialisers ([index] = and .member =) are accepted as a C99 convenience.",
  "{Arrays} struct {Strings} {Declarations}",
  "#include <stdio.h>\n\nstruct pt { int x, y, z; };\n\nint main(void)\n{\n    int a[5] = { 1, 2 };                 /* 1 2 0 0 0 */\n    char s[] = \"hello\";                  /* 6 bytes */\n    struct pt p = { .y = 7, .x = 1 };    /* z is 0 */\n\n    printf(\"%d %d %d %d\\n\", a[1], a[4], (int)sizeof s, p.y);\n    return 0;\n}",
  keys="initializer initialiser initialization"),
K("Functions", "Defining, declaring and calling functions.", ["type name(parameter-list) { body }", "type name(parameter-list);       /* prototype */", "name(arguments)"],
  "A prototype declares the parameter types so that arguments are checked and converted; call a function that has no prototype and you get 'Call to function with no prototype' (-wpro) and the arguments are only promoted. Put prototypes in headers and include them. Parameters are passed by value; pass a pointer to let the function change the caller's variable. Structures are passed and returned by value. Arrays are passed as pointers. Recursion is allowed.\n\nA parameter list ending in ... takes extra arguments: see {Variable arguments}. The parameter list (void) means none. A function has to be defined once in the program.",
  "return void main {Function pointers} {Variable arguments} static extern",
  "#include <stdio.h>\n\nstatic int fact(int n);               /* prototype */\n\nint main(void)\n{\n    printf(\"%d\\n\", fact(5));\n    return 0;\n}\n\nstatic int fact(int n)\n{\n    return n <= 1 ? 1 : n * fact(n - 1);\n}",
  keys="function prototype parameter argument call"),
K("main", "The function where the program starts.", ["int main(void)", "int main(int argc, char **argv)", "int main(int argc, char **argv, char **envp)"],
  "argc is the number of command-line words including the program name, argv[0..argc-1] are the words, argv[argc] is NULL. envp is the environment as NAME=value strings; the global environ holds the same. Set the arguments for Ctrl+F9 in Run|Arguments. The value returned from main (or passed to exit) is the exit code of the program; falling off the end gives 0. #pragma startup functions run before main, #pragma exit functions after it. Options|Libraries|Wildcard arguments expands * and ?.",
  "return exit {Libraries and linking}",
  "#include <stdio.h>\n\nint main(int argc, char **argv)\n{\n    int i;\n\n    printf(\"%d argument(s)\\n\", argc - 1);\n    for (i = 1; i < argc; i++)\n        printf(\"  %s\\n\", argv[i]);\n    return argc > 1 ? 0 : 1;\n}",
  keys="main argc argv envp"),
K("Function pointers", "Pointers to functions.", ["type (*name)(parameter-list);", "name = function;   name(args)   (*name)(args)"],
  "The name of a function converts to a pointer to it. A function pointer is called like a function. They are used for callbacks (qsort, bsearch, atexit, signal) and tables of handlers. Use typedef to make the declarations readable.",
  "typedef qsort {Functions} {Pointers}",
  "#include <stdio.h>\n\nstatic int add(int a, int b) { return a + b; }\nstatic int mul(int a, int b) { return a * b; }\n\nint main(void)\n{\n    int (*op[2])(int, int) = { add, mul };\n    int i;\n\n    for (i = 0; i < 2; i++)\n        printf(\"%d\\n\", op[i](6, 7));\n    return 0;\n}",
  keys="callback function-pointer"),
K("Variable arguments", "Functions with a variable number of parameters.", ["type name(type fixed, ...)", "va_list ap;  va_start(ap, fixed);  va_arg(ap, type);  va_end(ap);"],
  "Include <stdarg.h>. The function needs at least one fixed parameter; va_start(ap, last) starts after it, va_arg(ap, type) returns the next argument and va_end(ap) finishes. Arguments without a declared type are promoted: char and short become int, float becomes double, so ask for int and double, never char or float. The function must know how many arguments there are, e.g. from a count or a format string.",
  "{Functions} vprintf printf",
  "#include <stdio.h>\n#include <stdarg.h>\n\nstatic int sum(int count, ...)\n{\n    va_list ap;\n    int total = 0;\n\n    va_start(ap, count);\n    while (count-- > 0)\n        total += va_arg(ap, int);\n    va_end(ap);\n    return total;\n}\n\nint main(void)\n{\n    printf(\"%d\\n\", sum(4, 1, 2, 3, 4));\n    return 0;\n}",
  keys="stdarg ellipsis varargs"),
K("Bit fields", "Structure members with a given number of bits.", ["unsigned name : width;", "int name : width;", "int : width;     /* padding */", "int : 0;         /* start a new unit */"],
  "Bit fields are members of type int, signed int or unsigned int with a constant width of 1 to 32 bits. A plain int field is signed. Fields are packed from the least significant bit into 32-bit units and never straddle a unit. A field can be used like any integer lvalue, but & and sizeof cannot be applied to it. char, short and long fields are errors.",
  "struct union",
  "#include <stdio.h>\n\nstruct flags {\n    unsigned ready : 1;\n    unsigned mode  : 3;\n    int      delta : 4;      /* signed: -8 .. 7 */\n};\n\nint main(void)\n{\n    struct flags f = { 1, 5, -3 };\n\n    f.mode++;\n    printf(\"%d %d %d (size %d)\\n\", f.ready, f.mode, f.delta, (int)sizeof f);\n    return 0;\n}",
  keys="bitfield bit-field bits"),
K("Type conversions", "Implicit and explicit conversions.", [],
  "Usual conversions for arithmetic and comparisons:\n   1. char and short become int (integer promotion).\n   2. If either operand is double (or float) the other becomes double.\n   3. Otherwise if either is unsigned long both become unsigned long,\n      else if either is long both become long.\n   4. Otherwise if either is unsigned int both become unsigned int.\n   5. Otherwise both are int.\n\nAssignment converts to the type of the left side; a conversion to a narrower integer keeps the low bits; floating to integer truncates toward zero. Argument passing without a prototype promotes float to double. A signed value mixed with an unsigned one of the same size is treated as unsigned. Use a cast to make a conversion explicit.",
  "{Cast operator} {Integer types} unsigned {Functions}",
  "#include <stdio.h>\n\nint main(void)\n{\n    char c = 100;\n    int i = c * 3;           /* promoted to int: 300, no overflow */\n    unsigned char u = i;     /* low 8 bits: 44 */\n    int t = 3.99;            /* truncated: 3 */\n\n    printf(\"%d %d %d\\n\", i, u, t);\n    return 0;\n}",
  keys="conversion promotion"),
K("Expressions", "Operands, operators and their results.", [],
  "An expression is built from constants, variables, function calls and operators. An lvalue is an expression that designates an object (a variable, *p, a[i], s.m, p->m) and can be assigned to or have its address taken. The order of evaluation of operands and of function arguments is unspecified, so avoid side effects that depend on it. An expression followed by a semicolon is a statement; the warning 'Code has no effect' (-weff) catches expression statements that do nothing.",
  "{Operator precedence} {Arithmetic operators} {Assignment operators} {Type conversions} {Statements}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int a = 3, b = 4;\n    int hyp2 = a * a + b * b;\n\n    printf(\"%d\\n\", hyp2);\n    printf(\"%d\\n\", (a = 10) + b);   /* an assignment is an expression */\n    return 0;\n}",
  keys="expression lvalue"),
K("Statements", "The statements of C.", [],
  "   expression;                  expression statement\n   { declarations statements }  compound statement (block)\n   ;                            empty statement\n   {if} {else} {switch}              selection\n   {while} {do} {for}               iteration\n   {break} {continue} {goto} {return}   jumps\n   label:  case n:  default:    labelled statements\n\nThe warning 'Unreachable code' (-wrch) is given for a statement that follows return, break, continue or goto without a label in between.",
  "{Expressions} {Declarations}",
  "#include <stdio.h>\n\nint main(void)\n{\n    int i = 0;               /* declaration */\n\n    i++;                     /* expression statement */\n    {                        /* block */\n        int j = i * 2;\n        printf(\"%d\\n\", j);\n    }\n    ;                        /* empty statement */\n    return 0;\n}",
  keys="statement block compound"),
]

# preprocessor directives
PP = [
K("#include", "Inserts the text of another file.", ["#include <file>", "#include \"file\"", "#include macro"],
  "The <file> form searches the include directories (Options|Directories, fcc -I) and then the built-in headers; the \"file\" form searches the directory of the including file first. Includes may be nested. A header is read each time it is included, so guard your own headers with #ifndef. A macro that expands to either form can be used after #include.",
  "{#ifndef} {#define} {Preprocessor}",
  "#include <stdio.h>\n#include <string.h>\n\nint main(void)\n{\n    printf(\"%d\\n\", (int)strlen(\"include\"));\n    return 0;\n}",
  keys="include"),
K("#define", "Defines a macro.", ["#define NAME replacement", "#define NAME(parameters) replacement"],
  "Each later occurrence of NAME is replaced by the replacement text (and scanned again for macros). With parameters it is a function-like macro: the name must be directly followed by ( and the macro is only replaced when it is called with arguments. Enclose parameters and the whole replacement in parentheses to avoid precedence surprises, and remember that an argument with side effects is evaluated once for every use. A macro can also be defined on the command line (-Dname=value) or in Options|Compiler|Code generation|Defines. In the replacement # turns a parameter into a string and ## joins two tokens: {Stringizing and token pasting}.",
  "{#undef} {#ifdef} {Stringizing and token pasting} {Predefined macros}",
  "#include <stdio.h>\n\n#define SIZE 8\n#define SQUARE(x) ((x) * (x))\n#define MAX(a, b) ((a) > (b) ? (a) : (b))\n\nint main(void)\n{\n    printf(\"%d %d %d\\n\", SIZE, SQUARE(SIZE + 1), MAX(3, SIZE));\n    return 0;\n}",
  keys="define macro"),
K("#undef", "Removes a macro definition.", ["#undef NAME"],
  "Removing a macro that is not defined is not an error. Useful to redefine a macro or to switch off a library macro. Macros can also be removed from the command line (-Uname) or in Options|Compiler|Code generation|Undefine symbols.",
  "{#define} {#ifdef}",
  "#include <stdio.h>\n\n#define LEVEL 1\n#undef LEVEL\n#define LEVEL 2\n\nint main(void)\n{\n    printf(\"%d\\n\", LEVEL);\n    return 0;\n}",
  keys="undef"),
K("#if", "Compiles the following lines if an expression is true.", ["#if constant-expression"],
  "The expression is evaluated by the preprocessor with integer arithmetic. It may use integer constants, character constants, macros (undefined names count as 0), the operators of C, and defined(NAME). It must not contain sizeof, casts or floating-point numbers. The group ends at #elif, #else or #endif; conditional groups may be nested.",
  "{#elif} {#else} {#endif} {#ifdef} {#define}",
  "#include <stdio.h>\n\n#define VERSION 3\n\nint main(void)\n{\n#if VERSION >= 3 && defined(__linux__)\n    printf(\"new version on Linux\\n\");\n#else\n    printf(\"old version\\n\");\n#endif\n    return 0;\n}",
  keys="defined"),
K("#ifdef", "Compiles the following lines if a macro is defined.", ["#ifdef NAME"],
  "Same as #if defined(NAME). Often used with a macro that is set from the command line (-DDEBUG) to switch debugging code on and off.",
  "{#ifndef} {#if} {#endif} {#define}",
  "#include <stdio.h>\n\n#define DEBUG\n\nint main(void)\n{\n#ifdef DEBUG\n    printf(\"debug build\\n\");\n#endif\n    return 0;\n}",
  keys="ifdef"),
K("#ifndef", "Compiles the following lines if a macro is not defined.", ["#ifndef NAME"],
  "Same as #if !defined(NAME). The classic use is the include guard of a header file, which makes it harmless to include twice.",
  "{#ifdef} {#define} {#include}",
  "#include <stdio.h>\n\n#ifndef LIMIT\n#define LIMIT 10          /* default, can be set with -DLIMIT=20 */\n#endif\n\nint main(void)\n{\n    printf(\"%d\\n\", LIMIT);\n    return 0;\n}",
  keys="ifndef guard"),
K("#elif", "Else-if in a conditional group.", ["#elif constant-expression"],
  "Tested only if the preceding #if, #ifdef, #ifndef or #elif of the group was false.",
  "{#if} {#else} {#endif}",
  "#include <stdio.h>\n\n#define LEVEL 2\n\nint main(void)\n{\n#if LEVEL == 1\n    printf(\"one\\n\");\n#elif LEVEL == 2\n    printf(\"two\\n\");\n#else\n    printf(\"other\\n\");\n#endif\n    return 0;\n}",
  keys="elif"),
K("#else", "Alternative of a conditional group.", ["#else"],
  "The lines after #else are compiled if all earlier tests of the group were false. A group can have only one #else and it must come last.",
  "{#if} {#elif} {#endif}",
  "#include <stdio.h>\n\nint main(void)\n{\n#ifdef __x86_64__\n    printf(\"64-bit x86\\n\");\n#else\n    printf(\"something else\\n\");\n#endif\n    return 0;\n}",
  keys="else-directive"),
K("#endif", "Ends a conditional group.", ["#endif"],
  "Every #if, #ifdef and #ifndef needs a matching #endif in the same file; a missing one is reported at the end of the file.",
  "{#if} {#ifdef} {#ifndef}",
  "#include <stdio.h>\n\n#if 0\n    this text is skipped and never compiled\n#endif\n\nint main(void)\n{\n    printf(\"ok\\n\");\n    return 0;\n}",
  keys="endif"),
K("#line", "Changes the line number and file name used in messages.", ["#line number", "#line number \"file\""],
  "The next source line is treated as line number; __LINE__ and the compiler messages use it. With a file name __FILE__ changes too. Mostly used by programs that generate C source.",
  "{Predefined macros} {Preprocessor}",
  "#include <stdio.h>\n\n#line 500 \"generated.c\"\n\nint main(void)\n{\n    printf(\"%s:%d\\n\", __FILE__, __LINE__);   /* generated.c:504 */\n    return 0;\n}",
  keys="line"),
K("#error", "Stops the compilation with a message.", ["#error text"],
  "The text becomes the compiler message ('Error file line: #error directive: text'). Put it into a branch that must not be compiled to give a clear message for an unsupported configuration.",
  "{#if} {Preprocessor}",
  "#include <stdio.h>\n\n#ifndef __linux__\n#error This program needs Linux\n#endif\n\nint main(void)\n{\n    printf(\"built for Linux\\n\");\n    return 0;\n}",
  keys="error-directive"),
K("#pragma", "Compiler-specific instructions.", ["#pragma startup function [priority]", "#pragma exit function [priority]"],
  "startup names a void function without parameters that runs before main, exit one that runs after main returns or exit() is called; the function has to be declared before the pragma. The priority 0-255 (default 100) orders them: startup functions run from the lowest number up, exit functions from the highest down. Any other pragma is ignored.",
  "main {Libraries and linking} atexit",
  "#include <stdio.h>\n\nvoid begin(void) { printf(\"before main\\n\"); }\nvoid finish(void) { printf(\"after main\\n\"); }\n\n#pragma startup begin\n#pragma exit finish\n\nint main(void)\n{\n    printf(\"in main\\n\");\n    return 0;\n}",
  keys="pragma startup"),
K("Stringizing and token pasting", "The # and ## operators in macros.", ["#parameter", "token ## token"],
  "In the replacement text of a function-like macro, #x turns the argument into a string literal (quotes and backslashes inside are escaped) and a ## b joins the two tokens into one, which is then scanned for macros. Arguments next to # or ## are not macro-expanded first; to expand them use an extra macro level.",
  "{#define} {Preprocessor}",
  "#include <stdio.h>\n\n#define SHOW(e)   printf(\"%s = %d\\n\", #e, e)\n#define VAR(n)    value ## n\n\nint main(void)\n{\n    int value1 = 11, value2 = 22;\n\n    SHOW(3 * 4);\n    SHOW(VAR(2) + VAR(1));\n    return 0;\n}",
  keys="# ## stringize stringizing paste concatenation"),
]

